  "duplicates": [
    {
      "pair": [
        "proyecto4",
        "proyecto5"
      ],
      "verified": true
    },
    {
      "pair": [
        "proyecto8",
        "proyecto9"
      ],
      "verified": true
    }
  ],
  "decision": "Conservar pero marcar: permiten análisis de consistencia, no aportan diversidad de entrenamiento",
  "recommendation": "Al entrenar, deduplicar a 6 documentos únicos"
}

